def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits to the low end.

    x is an int in 0..255 and k is an int in 0..7. The result is in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    assert rotl8(0, 0) == 0
    assert rotl8(1, 0) == 1
    assert rotl8(0xAB, 0) == 0xAB
    assert rotl8(255, 0) == 255


def test_rotl8_wraps_high_bit() -> None:
    assert rotl8(0x80, 1) == 0x01
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b11000000, 2) == 0b00000011


def test_rotl8_single_bit_all_shifts() -> None:
    for k in range(8):
        assert rotl8(1, k) == 1 << k


def test_rotl8_nibble_swap() -> None:
    assert rotl8(0xAB, 4) == 0xBA
    assert rotl8(0x0F, 4) == 0xF0


def test_rotl8_all_ones_is_fixed() -> None:
    for k in range(8):
        assert rotl8(255, k) == 255


def test_rotl8_result_in_byte_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255
